import functools, time
from contextlib import contextmanager

# GENERATOR -- process huge file batch by batch
def read_batches(filepath, batch_size=1000):
    import csv
    with open(filepath, newline='') as f:
        reader = csv.DictReader(f)
        batch = []
        for row in reader:
            batch.append(row)
            if len(batch) >= batch_size:
                yield batch
                batch = []
        if batch: yield batch

for batch in read_batches('huge.csv'):
    print(f'Processing {len(batch)} rows')

# DECORATOR -- add timing to any function
def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        t0 = time.perf_counter()
        result = func(*args, **kwargs)
        print(f'{func.__name__} took {time.perf_counter()-t0:.3f}s')
        return result
    return wrapper

@timed
def load_data(path):
    import pandas as pd
    return pd.read_csv(path)

# CONTEXT MANAGER -- guaranteed cleanup
@contextmanager
def get_conn(conn_str):
    import pyodbc
    conn = pyodbc.connect(conn_str)
    try: yield conn
    finally: conn.close()  # always runs even on exception
